FuncDef: FuncDef = {
  <return_type: BType> <func_id: IDENT> "(" <params: (FuncFParams)?> ")" <block: Block> => {
    let mut vec = Vec::<FuncFParam>::new();
    if let Some(ps) = params {
      vec.extend(ps);
    }
    FuncDef::Default(return_type, func_id, vec, block)
  }
