/// Supported binary operators.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum BinaryOp {
  /// Not equal to.
  NotEq,
  /// Equal to.
  Eq,
  /// Greater than.
  Gt,
  /// Less than.
  Lt,
  /// Greater than or equal to.
  Ge,
  /// Less than or equal to.
  Le,
  /// Addition.
  Add,
  /// Subtraction.
  Sub,
  /// Multiplication.
  Mul,
  /// Division.
  Div,
  /// Modulo.
  Mod,
  /// Bitwise AND.
  And,
  /// Bitwise OR.

  /// Returns a reference to the values that the current value is used by.
  pub fn used_by(&self) -> &HashSet<Value> {
    &self.used_by
  }
}

impl Clone for ValueData {
  /// Clones the current value data, except the `used_by` set.
  fn clone(&self) -> Self {
    Self {
      ty: self.ty.clone(),
      name: self.name.clone(),
      kind: self.kind.clone(),
      used_by: HashSet::new(),
    }
  }
}

/// Kind of Koopa IR value.
#[derive(Clone, Debug)]
pub enum ValueKind {
  /// Integer constant.
  Integer(values::Integer),
  /// Zero initializer.
  ZeroInit(values::ZeroInit),
  /// Undefined value.
  Undef(values::Undef),
  /// Aggregate constant.
  Aggregate(values::Aggregate),
  /// Function argument reference.
  FuncArgRef(values::FuncArgRef),
  /// Basic block argument reference.
  BlockArgRef(values::BlockArgRef),
  /// Local memory allocation.
  Alloc(values::Alloc),
  /// Global memory allocation.
  GlobalAlloc(values::GlobalAlloc),
  /// Memory load.
  Load(values::Load),
  /// Memory store.
  Store(values::Store),
  /// Pointer calculation.
  GetPtr(values::GetPtr),
  /// Element pointer calculation.
  GetElemPtr(values::GetElemPtr),
  /// Binary operation.
  Binary(values::Binary),
  /// Conditional branch.
  Branch(values::Branch),
  /// Unconditional jump.
  Jump(values::Jump),
  /// Function call.
  Call(values::Call),
  /// Function return.
  Return(values::Return),
