//! Build a single component into Koopa IR.

use crate::ast_def::declarations::*;
use koopa::ir::{builder_traits::*, FunctionData, Program, Type, TypeKind, Value, ValueKind};

use super::{
    build_expressions::{IRExpBuildResult, IRExpBuildable},
    build_shape, create_new_local_value, get_array_type, get_valuedata, insert_local_instructions,
    IRBuildResult, IRBuildable, MyIRGeneratorInfo, SymbolTableEntry, create_new_block,
    insert_basic_blocks,
};

fn current_scope_has_symbol(my_ir_generator_info: &MyIRGeneratorInfo, name: &str) -> bool {
    my_ir_generator_info
        .symbol_tables
        .symbol_tables
        .last()
        .map(|table| table.contains_key(name))
        .unwrap_or(false)
}

fn create_i32_const(
    value: i32,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Value {
    if my_ir_generator_info.curr_func.is_none() {
        program.new_value().integer(value)
    } else {
        create_new_local_value(program, my_ir_generator_info).integer(value)
    }
}

fn create_const_aggregate(
    elems: Vec<Value>,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Value {
    if my_ir_generator_info.curr_func.is_none() {
        program.new_value().aggregate(elems)
    } else {
        create_new_local_value(program, my_ir_generator_info).aggregate(elems)
    }
}

fn create_zero_init_value(
    ty: Type,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Value {
    if my_ir_generator_info.curr_func.is_none() {
        program.new_value().zero_init(ty)
    } else {
        create_new_local_value(program, my_ir_generator_info).zero_init(ty)
    }
}

fn create_int_array_type(shape: &[usize]) -> Type {
    let mut ty = Type::get_i32();
    for len in shape.iter().rev() {
        ty = Type::get_array(ty, *len);
    }
    ty
}

fn build_scalar_init_value(
    init: &InitVal,
    require_const: bool,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<Value, String> {
    match init {
        InitVal::Exp(exp) => match exp.build(program, my_ir_generator_info)? {
            IRExpBuildResult::Const(int) => Ok(create_i32_const(int, program, my_ir_generator_info)),
            IRExpBuildResult::Value(value) => {
                if require_const {
                    Err(format!("Non-constant scalar initializer: {:?}", init))
                } else {
                    Ok(value)
                }
            }
        },
        InitVal::Aggregate(childs) => match childs.len() {
            0 => Ok(create_i32_const(0, program, my_ir_generator_info)),
            1 => build_scalar_init_value(&childs[0], require_const, program, my_ir_generator_info),
            _ => Err(format!("Too many elements in scalar initializer: {:?}", init)),
        },
    }
}

fn build_array_init_value(
    init: &InitVal,
    shape: &[usize],
    require_const: bool,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<Value, String> {
    match init {
        InitVal::Aggregate(childs) => {
            let (value, consumed) = build_new_aggregate(
                shape,
                childs,
                require_const,
                program,
                my_ir_generator_info,
            )?;
            if consumed != childs.len() {
                return Err(format!("Too many elements in array initializer: {:?}", init));
            }
            Ok(value)
        }
        _ => Err(format!("Array initializer must be an aggregate: {:?}", init)),
    }
}

impl IRBuildable for FuncDef {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        let FuncDef::Default(ret_type, ident, params, block) = self;
        if my_ir_generator_info.check_duplicate_global_symbol(&ident.content) {
            return Err(format!("Duplicate global symbol: {}", ident.content));
        }

        let mut param_defs = vec![];
        let mut param_types = vec![];
        for param in params {
            let FuncFParam::Default(btype, param_ident, shape_exps) = param;
            let param_ty = match shape_exps {
                None => Type::get(btype.content.clone()),
                Some(shape_exps) => {
                    let shape = build_shape(shape_exps, program, my_ir_generator_info)?;
                    Type::get_pointer(Type::get(get_array_type(btype, &shape)))
                }
            };
            param_defs.push((Some(format!("@{}", param_ident.content)), param_ty.clone()));
            param_types.push(param_ty);
        }

        let func = program.new_func(FunctionData::with_param_names(
            format!("@{}", ident.content),
            param_defs,
            Type::get(ret_type.content.clone()),
        ));
        my_ir_generator_info
            .function_table
            .insert(ident.content.clone(), func);

        my_ir_generator_info.curr_func = Some(func);
        let entry = create_new_block(program, my_ir_generator_info, "entry");
        insert_basic_blocks(program, my_ir_generator_info, [entry]);
        my_ir_generator_info.curr_block = Some(entry);
        my_ir_generator_info.symbol_tables.add_new_table();

        let params_values = program.func(func).params().to_vec();
        for ((param, param_value), param_ty) in params
            .iter()
            .zip(params_values.into_iter())
            .zip(param_types.into_iter())
        {
            let FuncFParam::Default(_btype, param_ident, _shape_exps) = param;
            if current_scope_has_symbol(my_ir_generator_info, &param_ident.content) {
                return Err(format!(
                    "Duplicate parameter in function '{}': {}",
                    ident.content, param_ident.content
                ));
            }
            let alloc = create_new_local_value(program, my_ir_generator_info).alloc(param_ty.clone());
            program
                .func_mut(func)
                .dfg_mut()
                .set_value_name(alloc, Some(format!("@{}", param_ident.content)));
            let store = create_new_local_value(program, my_ir_generator_info).store(param_value, alloc);
            insert_local_instructions(program, my_ir_generator_info, [alloc, store]);
            my_ir_generator_info.symbol_tables.insert(
                param_ident.content.clone(),
                SymbolTableEntry::Variable(param_ty.kind().clone(), alloc),
            );
        }

        let block_result = block.build(program, my_ir_generator_info)?;
        if let IRBuildResult::OK = block_result {
            let ret = if Type::get(ret_type.content.clone()).is_unit() {
                create_new_local_value(program, my_ir_generator_info).ret(None)
            } else {
                let zero = create_i32_const(0, program, my_ir_generator_info);
                create_new_local_value(program, my_ir_generator_info).ret(Some(zero))
            };
            insert_local_instructions(program, my_ir_generator_info, [ret]);
        }

        my_ir_generator_info.curr_block = None;
        my_ir_generator_info.curr_func = None;
        Ok(IRBuildResult::OK)
    }
}

impl IRBuildable for Block {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        let Block::Default(stmts) = self;
        let mut block_result = IRBuildResult::OK;
        for stmt in stmts {
            let result = stmt.build(program, my_ir_generator_info)?;
            // Ignore everything after the return statement.
            if let IRBuildResult::EARLYSTOPPING = result {
                block_result = result;
                break;
            }
        }
        my_ir_generator_info.symbol_tables.delete_new_table();
        Ok(block_result)
    }
}

