            )?;

//! Build a single component into Koopa IR.

use crate::ast_def::expressions::*;
use koopa::ir::{builder_traits::*, Program, Type, TypeKind, Value};

use super::{
    create_new_block, create_new_local_value, get_valuedata,
    insert_basic_blocks, insert_local_instructions, MyIRGeneratorInfo, SymbolTableEntry,
};

fn create_i32_const(
    value: i32,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Value {
    if my_ir_generator_info.curr_func.is_none() {
        program.new_value().integer(value)
    } else {
        create_new_local_value(program, my_ir_generator_info).integer(value)
    }
}

fn build_bool_result(
    result: IRExpBuildResult,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<IRExpBuildResult, String> {
    match result {
        IRExpBuildResult::Const(int) => Ok(IRExpBuildResult::Const((int != 0) as i32)),
        IRExpBuildResult::Value(value) => {
            let zero = create_i32_const(0, program, my_ir_generator_info);
            let not_zero = create_new_local_value(program, my_ir_generator_info)
                .binary(koopa::ir::BinaryOp::NotEq, value, zero);
            insert_local_instructions(program, my_ir_generator_info, [not_zero]);
            Ok(IRExpBuildResult::Value(not_zero))
        }
    }
}

fn op_on_consts(op: koopa::ir::BinaryOp, lhs: i32, rhs: i32) -> i32 {
    match op {
        koopa::ir::BinaryOp::NotEq => (lhs != rhs) as i32,
        koopa::ir::BinaryOp::Eq => (lhs == rhs) as i32,
        koopa::ir::BinaryOp::Gt => (lhs > rhs) as i32,
        koopa::ir::BinaryOp::Lt => (lhs < rhs) as i32,
        koopa::ir::BinaryOp::Ge => (lhs >= rhs) as i32,
        koopa::ir::BinaryOp::Le => (lhs <= rhs) as i32,
        koopa::ir::BinaryOp::Add => lhs + rhs,
        koopa::ir::BinaryOp::Sub => lhs - rhs,
        koopa::ir::BinaryOp::Mul => lhs * rhs,
        koopa::ir::BinaryOp::Div => lhs / rhs,
        koopa::ir::BinaryOp::Mod => lhs % rhs,
        koopa::ir::BinaryOp::And => lhs & rhs,
        koopa::ir::BinaryOp::Or => lhs | rhs,
        koopa::ir::BinaryOp::Xor => lhs ^ rhs,
        koopa::ir::BinaryOp::Shl => lhs << rhs,
        koopa::ir::BinaryOp::Shr => ((lhs as u32) >> rhs) as i32,
        koopa::ir::BinaryOp::Sar => lhs >> rhs,
    }
}

/// IR expression building result. If the expression is a constant expression, returns the i32 result.
/// Otherwise, returns the Koopa IR Value.
pub enum IRExpBuildResult {
    Const(i32),
    Value(Value),
}
pub trait IRExpBuildable {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRExpBuildResult, String>;
}

impl IRExpBuildable for Exp {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRExpBuildResult, String> {
        match self {
            Exp::LOrExp(lor_exp) => lor_exp.build(program, my_ir_generator_info),
        }
    }
}

fn build_binary_from_build_results(
    result1: IRExpBuildResult,
    result2: IRExpBuildResult,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
    binary_op: koopa::ir::BinaryOp,
) -> Result<IRExpBuildResult, String> {
    match (result1, result2) {
        (IRExpBuildResult::Const(lhs), IRExpBuildResult::Const(rhs)) => {
            Ok(IRExpBuildResult::Const(op_on_consts(binary_op, lhs, rhs)))
        }
        (lhs, rhs) => {
            let lhs_value = match lhs {
                IRExpBuildResult::Const(int) => create_i32_const(int, program, my_ir_generator_info),
                IRExpBuildResult::Value(value) => value,
            };
            let rhs_value = match rhs {
                IRExpBuildResult::Const(int) => create_i32_const(int, program, my_ir_generator_info),
                IRExpBuildResult::Value(value) => value,
            };
            let value = create_new_local_value(program, my_ir_generator_info)
                .binary(binary_op, lhs_value, rhs_value);
            insert_local_instructions(program, my_ir_generator_info, [value]);
            Ok(IRExpBuildResult::Value(value))
        }
    }
}

impl IRExpBuildable for LOrExp {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRExpBuildResult, String> {
        match self {
            LOrExp::LAndExp(exp) => exp.build(program, my_ir_generator_info),
            LOrExp::BinaryLOrExp(lhs, rhs) => {
                let lhs_result = lhs.build(program, my_ir_generator_info)?;
                match lhs_result {
                    IRExpBuildResult::Const(int) => {
                        if int != 0 {
                            Ok(IRExpBuildResult::Const(1))
                        } else {
                            build_bool_result(rhs.build(program, my_ir_generator_info)?, program, my_ir_generator_info)
                        }
                    }
                    IRExpBuildResult::Value(lhs_value) => {
                        let result_ptr =
                            create_new_local_value(program, my_ir_generator_info).alloc(Type::get_i32());
                        insert_local_instructions(program, my_ir_generator_info, [result_ptr]);

                        let true_bb = create_new_block(program, my_ir_generator_info, "lor_true");
                        let rhs_bb = create_new_block(program, my_ir_generator_info, "lor_rhs");
                        let end_bb = create_new_block(program, my_ir_generator_info, "lor_end");
                        insert_basic_blocks(program, my_ir_generator_info, [true_bb, rhs_bb, end_bb]);

                        let br = create_new_local_value(program, my_ir_generator_info)
                            .branch(lhs_value, true_bb, rhs_bb);
                        insert_local_instructions(program, my_ir_generator_info, [br]);

                        my_ir_generator_info.curr_block = Some(true_bb);
                        let one = create_i32_const(1, program, my_ir_generator_info);
                        let store_true = create_new_local_value(program, my_ir_generator_info)
                            .store(one, result_ptr);
                        let jump_true =
                            create_new_local_value(program, my_ir_generator_info).jump(end_bb);
                        insert_local_instructions(
                            program,
                            my_ir_generator_info,
                            [store_true, jump_true],
                        );

                        my_ir_generator_info.curr_block = Some(rhs_bb);
                        let rhs_bool = match build_bool_result(
                            rhs.build(program, my_ir_generator_info)?,
                            program,
                            my_ir_generator_info,
                        )? {
                            IRExpBuildResult::Const(int) => {
                                create_i32_const(int, program, my_ir_generator_info)
                            }
                            IRExpBuildResult::Value(value) => value,
                        };
                        let store_rhs = create_new_local_value(program, my_ir_generator_info)
                            .store(rhs_bool, result_ptr);
                        let jump_rhs =
                            create_new_local_value(program, my_ir_generator_info).jump(end_bb);
                        insert_local_instructions(
                            program,
                            my_ir_generator_info,
                            [store_rhs, jump_rhs],
                        );

                        my_ir_generator_info.curr_block = Some(end_bb);
                        let load_result =
                            create_new_local_value(program, my_ir_generator_info).load(result_ptr);
                        insert_local_instructions(program, my_ir_generator_info, [load_result]);
                        Ok(IRExpBuildResult::Value(load_result))
                    }
                }
            }
        }
    }
}

impl IRExpBuildable for LAndExp {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRExpBuildResult, String> {
        match self {
            LAndExp::EqExp(exp) => exp.build(program, my_ir_generator_info),
            LAndExp::BinaryLAndExp(lhs, rhs) => {
                let lhs_result = lhs.build(program, my_ir_generator_info)?;
                match lhs_result {
                    IRExpBuildResult::Const(int) => {
                        if int == 0 {
                            Ok(IRExpBuildResult::Const(0))
                        } else {
                            build_bool_result(rhs.build(program, my_ir_generator_info)?, program, my_ir_generator_info)
                        }
                    }
                    IRExpBuildResult::Value(lhs_value) => {
                        let result_ptr =
                            create_new_local_value(program, my_ir_generator_info).alloc(Type::get_i32());
                        insert_local_instructions(program, my_ir_generator_info, [result_ptr]);

                        let false_bb = create_new_block(program, my_ir_generator_info, "land_false");
                        let rhs_bb = create_new_block(program, my_ir_generator_info, "land_rhs");
                        let end_bb = create_new_block(program, my_ir_generator_info, "land_end");
                        insert_basic_blocks(program, my_ir_generator_info, [false_bb, rhs_bb, end_bb]);

                        let br = create_new_local_value(program, my_ir_generator_info)
                            .branch(lhs_value, rhs_bb, false_bb);
                        insert_local_instructions(program, my_ir_generator_info, [br]);

                        my_ir_generator_info.curr_block = Some(false_bb);
                        let zero = create_i32_const(0, program, my_ir_generator_info);
                        let store_false = create_new_local_value(program, my_ir_generator_info)
                            .store(zero, result_ptr);
                        let jump_false =
                            create_new_local_value(program, my_ir_generator_info).jump(end_bb);
                        insert_local_instructions(
                            program,
                            my_ir_generator_info,
                            [store_false, jump_false],
                        );

                        my_ir_generator_info.curr_block = Some(rhs_bb);
                        let rhs_bool = match build_bool_result(
                            rhs.build(program, my_ir_generator_info)?,
                            program,
                            my_ir_generator_info,
                        )? {
                            IRExpBuildResult::Const(int) => {
                                create_i32_const(int, program, my_ir_generator_info)
                            }
                            IRExpBuildResult::Value(value) => value,
                        };
                        let store_rhs = create_new_local_value(program, my_ir_generator_info)
                            .store(rhs_bool, result_ptr);
                        let jump_rhs =
                            create_new_local_value(program, my_ir_generator_info).jump(end_bb);
                        insert_local_instructions(
                            program,
                            my_ir_generator_info,
                            [store_rhs, jump_rhs],
                        );

                        my_ir_generator_info.curr_block = Some(end_bb);
                        let load_result =
                            create_new_local_value(program, my_ir_generator_info).load(result_ptr);
                        insert_local_instructions(program, my_ir_generator_info, [load_result]);
                        Ok(IRExpBuildResult::Value(load_result))
                    }
                }
            }
        }
    }
}

