    }

    let temp = create_new_local_value(program, my_ir_generator_info).alloc(create_int_array_type(shape));
    insert_local_instructions(program, my_ir_generator_info, [temp]);
    for (idx, elem) in elems.into_iter().enumerate() {
        let idx_value = create_i32_const(idx as i32, program, my_ir_generator_info);
        let elem_ptr =
            create_new_local_value(program, my_ir_generator_info).get_elem_ptr(temp, idx_value);
        insert_local_instructions(program, my_ir_generator_info, [elem_ptr]);
        aggregate_to_store_insts(elem, elem_ptr, program, my_ir_generator_info)?;
    }
    Ok((temp, used))
}

fn aggregate_to_store_insts(
    aggr: Value,
    aggr_ptr: Value,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<(), String> {
    let aggr_data = get_valuedata(aggr, program, my_ir_generator_info);
    match aggr_data.ty().kind() {
        TypeKind::Int32 => {
            let store = create_new_local_value(program, my_ir_generator_info).store(aggr, aggr_ptr);
            insert_local_instructions(program, my_ir_generator_info, [store]);
            Ok(())
        }
        TypeKind::Array(_, _) => match aggr_data.kind() {
            ValueKind::Aggregate(aggregate) => {
                let elems = aggregate.elems().to_vec();
                for (idx, elem) in elems.into_iter().enumerate() {
                    let idx_value = create_i32_const(idx as i32, program, my_ir_generator_info);
                    let elem_ptr = create_new_local_value(program, my_ir_generator_info)
                        .get_elem_ptr(aggr_ptr, idx_value);
                    insert_local_instructions(program, my_ir_generator_info, [elem_ptr]);
                    aggregate_to_store_insts(elem, elem_ptr, program, my_ir_generator_info)?;
                }
                Ok(())
            }
            ValueKind::ZeroInit(_) => {
                let zero = create_zero_init_value(aggr_data.ty().clone(), program, my_ir_generator_info);
                let store = create_new_local_value(program, my_ir_generator_info).store(zero, aggr_ptr);
                insert_local_instructions(program, my_ir_generator_info, [store]);
                Ok(())
            }
            _ => Err(format!("Unexpected array aggregate value: {:?}", aggr_data.kind())),
        },
        TypeKind::Pointer(base) => match base.kind() {
            TypeKind::Int32 => {
                let load = create_new_local_value(program, my_ir_generator_info).load(aggr);
                let store = create_new_local_value(program, my_ir_generator_info).store(load, aggr_ptr);
                insert_local_instructions(program, my_ir_generator_info, [load, store]);
                Ok(())
            }
            TypeKind::Array(_, len) => {
                for idx in 0..*len {
                    let idx_value = create_i32_const(idx as i32, program, my_ir_generator_info);
                    let src_elem_ptr =
                        create_new_local_value(program, my_ir_generator_info).get_elem_ptr(aggr, idx_value);
                    let dst_elem_ptr = create_new_local_value(program, my_ir_generator_info)
                        .get_elem_ptr(aggr_ptr, idx_value);
                    insert_local_instructions(
                        program,
                        my_ir_generator_info,
                        [src_elem_ptr, dst_elem_ptr],
                    );
                    aggregate_to_store_insts(
                        src_elem_ptr,
                        dst_elem_ptr,
                        program,
                        my_ir_generator_info,
                    )?;
                }
                Ok(())
            }
            _ => Err(format!(
                "Unsupported aggregate pointer source type: {:?}",
                aggr_data.ty()
            )),
        },
        _ => Err(format!("Unsupported aggregate source type: {:?}", aggr_data.ty())),
    }
}

impl InitVal {
    fn build(
        &self,
        shape: &[usize],
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRInitValBuildResult, String> {
        let is_global = my_ir_generator_info.curr_func.is_none();
        match self {
            InitVal::Exp(exp) => match exp.build(program, my_ir_generator_info)? {
                IRExpBuildResult::Const(int) => Ok(IRInitValBuildResult::Const(int)),
                IRExpBuildResult::Value(value) => {
                    if is_global {
                        Err(format!(
                            "Non-constant expression '{:?}' in global variable initval: {:?}",
                            exp, self
                        ))
                    } else {
                        Ok(IRInitValBuildResult::Var(value))
                    }
                }
            },
            InitVal::Aggregate(childs) => {
                let (value, _) =
                    build_new_aggregate(shape, childs, is_global, program, my_ir_generator_info)?;
                Ok(IRInitValBuildResult::Aggregate(value))
            }
        }
    }
}

