impl IRExpBuildable for UnaryExp {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRExpBuildResult, String> {
        match self {
            UnaryExp::PrimaryExp(exp) => exp.build(program, my_ir_generator_info),
            UnaryExp::PlusUnaryExp(exp) => exp.build(program, my_ir_generator_info),
            UnaryExp::MinusUnaryExp(exp) => match exp.build(program, my_ir_generator_info)? {
                IRExpBuildResult::Const(int) => Ok(IRExpBuildResult::Const(-int)),
                IRExpBuildResult::Value(value) => {
                    let zero = create_i32_const(0, program, my_ir_generator_info);
                    let result = create_new_local_value(program, my_ir_generator_info)
                        .binary(koopa::ir::BinaryOp::Sub, zero, value);
                    insert_local_instructions(program, my_ir_generator_info, [result]);
                    Ok(IRExpBuildResult::Value(result))
                }
            },
            UnaryExp::NotUnaryExp(exp) => match exp.build(program, my_ir_generator_info)? {
                IRExpBuildResult::Const(int) => Ok(IRExpBuildResult::Const((int == 0) as i32)),
                IRExpBuildResult::Value(value) => {
                    let zero = create_i32_const(0, program, my_ir_generator_info);
                    let result = create_new_local_value(program, my_ir_generator_info)
                        .binary(koopa::ir::BinaryOp::Eq, value, zero);
                    insert_local_instructions(program, my_ir_generator_info, [result]);
                    Ok(IRExpBuildResult::Value(result))
                }
            },
            UnaryExp::FuncCall(ident, args) => {
                let func = my_ir_generator_info
                    .function_table
                    .get(&ident.content)
                    .copied()
                    .ok_or_else(|| format!("Unknown function: {}", ident.content))?;
                let func_ty = program.func(func).ty().clone();
                let (param_tys, ret_ty) = match func_ty.kind() {
                    TypeKind::Function(param_tys, ret_ty) => (param_tys.clone(), ret_ty.clone()),
                    _ => return Err(format!("Symbol is not a function: {}", ident.content)),
                };
                if args.len() != param_tys.len() {
                    return Err(format!(
                        "Function '{}' expects {} args, got {}",
                        ident.content,
                        param_tys.len(),
                        args.len()
                    ));
                }

                let mut arg_values = vec![];
                for (arg, param_ty) in args.iter().zip(param_tys.iter()) {
                    let value = match arg.build(program, my_ir_generator_info)? {
                        IRExpBuildResult::Const(int) => {
                            if !param_ty.is_i32() {
                                return Err(format!(
                                    "Type mismatch when calling '{}': expected {}, got i32 constant",
                                    ident.content, param_ty
                                ));
                            }
                            create_i32_const(int, program, my_ir_generator_info)
                        }
                        IRExpBuildResult::Value(value) => {
                            if get_valuedata(value, program, my_ir_generator_info).ty() != param_ty {
                                return Err(format!(
                                    "Type mismatch when calling '{}': expected {}, got {}",
                                    ident.content,
                                    param_ty,
                                    get_valuedata(value, program, my_ir_generator_info).ty()
                                ));
                            }
                            value
                        }
                    };
                    arg_values.push(value);
                }

                let call = create_new_local_value(program, my_ir_generator_info).call(func, arg_values);
                insert_local_instructions(program, my_ir_generator_info, [call]);
                if ret_ty.is_unit() {
                    Ok(IRExpBuildResult::Value(call))
                } else {
                    Ok(IRExpBuildResult::Value(call))
                }
            }
        }
    }
}

impl IRExpBuildable for PrimaryExp {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRExpBuildResult, String> {
        match self {
            PrimaryExp::BracedExp(exp) => exp.build(program, my_ir_generator_info),
            PrimaryExp::LVal(lval) => match lval.build(program, my_ir_generator_info)? {
                IRLValBuildResult::Const(int) => Ok(IRExpBuildResult::Const(int)),
                IRLValBuildResult::TempVal(value) => Ok(IRExpBuildResult::Value(value)),
                IRLValBuildResult::Addr(addr) => {
                    let load = create_new_local_value(program, my_ir_generator_info).load(addr);
                    insert_local_instructions(program, my_ir_generator_info, [load]);
                    Ok(IRExpBuildResult::Value(load))
                }
            },
            PrimaryExp::Number(number) => number.build(program, my_ir_generator_info),
        }
    }
}

#[derive(Debug)]
pub enum IRLValBuildResult {
    Const(i32),
    TempVal(Value),
    Addr(Value),
}

impl LVal {
    pub fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRLValBuildResult, String> {
        let LVal::Default(ident, index_exps) = self;
        match my_ir_generator_info.symbol_tables.get(&ident.content) {
            Some(SymbolTableEntry::Variable(_, ptr)) => {

            Some(SymbolTableEntry::Variable(_, ptr)) => {
                let ptr = ptr.clone();
                // Build indexes.
                let mut index_values = vec![];
                for exp in index_exps {
                    let build = exp.build(program, my_ir_generator_info)?;
                    index_values.push(match build {
                        IRExpBuildResult::Const(int) => {
                            create_new_local_value(program, my_ir_generator_info)
                                .integer(int)
                        }
                        IRExpBuildResult::Value(value) => value,
                    })
                }
                // Get element.
                let result = get_element_in_ndarray(ptr, &index_values, program, my_ir_generator_info);
                Ok(result)
            }
            Some(SymbolTableEntry::Constant(_lval_type, int)) => Ok(IRLValBuildResult::Const(*int)),
            None => Err(format!("Undeclared LVal symbol: {}", ident.content)),
        }
    }
}

impl IRExpBuildable for Number {
    fn build(
        &self,
        _program: &mut Program,
        _my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRExpBuildResult, String> {
        match self {
            Number::INTCONST(int) => Ok(IRExpBuildResult::Const(*int)),
        }
    }
}

/// This is a LVal Value. It should always be a local Value.
fn get_element_in_ndarray(
    array_or_pointer: Value,
    indexes: &[Value],
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> IRLValBuildResult {
    let mut curr = array_or_pointer;
    let mut first_pointer_index = false;
    let mut curr_ty = get_valuedata(curr, program, my_ir_generator_info).ty().clone();

    if let TypeKind::Pointer(inner) = curr_ty.kind() {
        if matches!(inner.kind(), TypeKind::Pointer(_)) {
            let load = create_new_local_value(program, my_ir_generator_info).load(curr);
            insert_local_instructions(program, my_ir_generator_info, [load]);
            curr = load;
            curr_ty = get_valuedata(curr, program, my_ir_generator_info).ty().clone();
            if indexes.is_empty() {
                return IRLValBuildResult::TempVal(curr);
            }
            first_pointer_index = true;
        }
    }

    for index in indexes {
        let next = if first_pointer_index {
            first_pointer_index = false;
            create_new_local_value(program, my_ir_generator_info).get_ptr(curr, *index)
        } else {
            create_new_local_value(program, my_ir_generator_info).get_elem_ptr(curr, *index)
        };
        insert_local_instructions(program, my_ir_generator_info, [next]);
        curr = next;
        curr_ty = get_valuedata(curr, program, my_ir_generator_info).ty().clone();
    }

    match curr_ty.kind() {
        TypeKind::Pointer(base) => match base.kind() {
            TypeKind::Array(_, _) => {
                if indexes.is_empty() && !matches!(
                    get_valuedata(array_or_pointer, program, my_ir_generator_info)
                        .ty()
                        .kind(),
                    TypeKind::Pointer(inner)
                        if matches!(inner.kind(), TypeKind::Pointer(_))
                ) {
                    let zero = create_i32_const(0, program, my_ir_generator_info);
                    let first_elem = create_new_local_value(program, my_ir_generator_info)
                        .get_elem_ptr(curr, zero);
                    insert_local_instructions(program, my_ir_generator_info, [first_elem]);
                    IRLValBuildResult::TempVal(first_elem)
                } else if indexes.is_empty() {
                    IRLValBuildResult::TempVal(curr)
                } else {
                    let zero = create_i32_const(0, program, my_ir_generator_info);
                    let first_elem = create_new_local_value(program, my_ir_generator_info)
                        .get_elem_ptr(curr, zero);
                    insert_local_instructions(program, my_ir_generator_info, [first_elem]);
                    IRLValBuildResult::TempVal(first_elem)
                }
            }
            _ => IRLValBuildResult::Addr(curr),
        },
        _ => IRLValBuildResult::TempVal(curr),
    }
}

//! This module is the backend of my compiler.
//! It converts the Koopa IR into assembly code.

mod build_assembly;
use std::collections::HashMap;
use std::io::Write;

use build_assembly::AssemblyBuildable;
use koopa::ir::{FunctionData, Program, Value};

pub fn generate_assembly(program: &Program, output_file: &mut std::fs::File) -> Result<(), String> {
    let codes = program.build(program)?;
    for code in codes {
        writeln!(output_file, "{}", code).expect("Write error. ");
    }
    Ok(())
}

const REGISTER_NAMES: [&str; 32] = [
    "zero", "ra", "sp", "gp", "tp", "t0", "t1", "t2", "fp", "s1", "a0", "a1", "a2", "a3", "a4",
    "a5", "a6", "a7", "s2", "s3", "s4", "s5", "s6", "s7", "s8", "s9", "s10", "s11", "t3", "t4",
    "t5", "x31",
