//! Convert a single Koopa IR component into assembly code.

use std::collections::HashMap;

use crate::assembly_builder::{assembly_symbol_name, is_short_int, REG_RA, REG_X31};

use super::{
    MyBBValueTable, ARG_SIZE, REGISTER_FOR_ARGS, REGISTER_NAMES, REG_A0, REG_SP,
};
use koopa::ir::{
    entities::{BasicBlock, ValueData, ValueKind},
    values::{Aggregate, Binary},
    FunctionData, Program, Type, TypeKind, Value,
};

pub trait AssemblyBuildable {
    fn build(&self, program: &Program) -> Result<Vec<String>, String>;
}

fn align_to(value: usize, align: usize) -> usize {
    ((value + align - 1) / align) * align
}

fn bb_label(bb: BasicBlock, fd: &FunctionData, fallback_index: usize) -> String {
    fd.dfg()
        .bb(bb)
        .name()
        .as_ref()
        .map(|name| format!(".{}", assembly_symbol_name(name)))
        .unwrap_or_else(|| format!(".bb{}", fallback_index))
}

fn stack_adjust_prologue(stack_size: usize) -> Vec<String> {
    if stack_size == 0 {
        vec![]
    } else if is_short_int(-(stack_size as isize)) {
        vec![format!(
            "  addi\t{}, {}, -{}",
            REGISTER_NAMES[REG_SP], REGISTER_NAMES[REG_SP], stack_size
        )]
    } else {
        vec![
            format!("  li\t{}, {}", REGISTER_NAMES[REG_X31], stack_size),
            format!(
                "  sub\t{}, {}, {}",
                REGISTER_NAMES[REG_SP], REGISTER_NAMES[REG_SP], REGISTER_NAMES[REG_X31]
            ),
        ]
    }
}

fn stack_adjust_epilogue(stack_size: usize) -> Vec<String> {
    if stack_size == 0 {
        vec![]
    } else if is_short_int(stack_size as isize) {
        vec![format!(
            "  addi\t{}, {}, {}",
            REGISTER_NAMES[REG_SP], REGISTER_NAMES[REG_SP], stack_size
        )]
    } else {
        vec![
            format!("  li\t{}, {}", REGISTER_NAMES[REG_X31], stack_size),
            format!(
                "  add\t{}, {}, {}",
                REGISTER_NAMES[REG_SP], REGISTER_NAMES[REG_SP], REGISTER_NAMES[REG_X31]
            ),
        ]
    }
}

fn add_reg_offset(dst_reg: usize, base_reg: usize, offset: isize) -> Vec<String> {
    if is_short_int(offset) {
        vec![format!(
            "  addi\t{}, {}, {}",
            REGISTER_NAMES[dst_reg], REGISTER_NAMES[base_reg], offset
        )]
    } else {
        vec![
            format!("  li\t{}, {}", REGISTER_NAMES[REG_X31], offset),
            format!(
                "  add\t{}, {}, {}",
                REGISTER_NAMES[dst_reg], REGISTER_NAMES[base_reg], REGISTER_NAMES[REG_X31]
            ),
        ]
    }
}

fn clear_tracked_registers(value_table: &mut MyBBValueTable) -> Vec<String> {
    let mut codes = value_table.store_global_variables();
    codes.extend(value_table.store_local_variables());
    codes
}

fn discard_caller_saved_registers(value_table: &mut MyBBValueTable) {
    for reg in REGISTER_FOR_ARGS {
        value_table.__free_user(reg);
    }
    for reg in super::REGISTER_FOR_TEMP {
        value_table.__free_user(reg);
    }
    value_table.__free_user(REG_X31);
}

fn lookup_value_data<'a>(
    value: Value,
    program: &'a Program,
    fd: &'a FunctionData,
) -> ValueData {
    if value.is_global() {
        program.borrow_value(value).clone()
    } else {
        fd.dfg().value(value).clone()
    }
}

fn emit_store_value(
    value: Value,
    addr_reg: usize,
    value_table: &mut MyBBValueTable,
    codes: &mut Vec<String>,
) -> Result<(), String> {
    let value_data = lookup_value_data(value, value_table.program, value_table.fd);
    match value_data.ty().kind() {
        TypeKind::Int32 | TypeKind::Pointer(_) => {
            match value_data.kind() {
                ValueKind::ZeroInit(_) => {
                    codes.push(format!(
                        "  sw\t{}, 0({})",
                        REGISTER_NAMES[0], REGISTER_NAMES[addr_reg]
                    ));
                }
                _ => {
                    let (reg, value_codes) = value_table.want_to_visit_value(value, true, None);
                    codes.extend(value_codes);
                    codes.push(format!(
                        "  sw\t{}, 0({})",
                        REGISTER_NAMES[reg], REGISTER_NAMES[addr_reg]
                    ));
                }
            }
            Ok(())
        }
        TypeKind::Array(base_ty, len) => match value_data.kind() {
            ValueKind::Aggregate(aggregate) => {
                for (idx, elem) in aggregate.elems().iter().copied().enumerate() {
                    let (sub_addr_reg, addr_codes) = value_table.get_tmp_reg();
                    codes.extend(addr_codes);
                    codes.extend(add_reg_offset(
                        sub_addr_reg,
                        addr_reg,
                        (idx * base_ty.size()) as isize,
                    ));
                    emit_store_value(elem, sub_addr_reg, value_table, codes)?;
                }
                Ok(())
            }
            ValueKind::ZeroInit(_) => {
                for idx in 0..*len {
                    let (sub_addr_reg, addr_codes) = value_table.get_tmp_reg();
                    codes.extend(addr_codes);
                    codes.extend(add_reg_offset(
                        sub_addr_reg,
                        addr_reg,
                        (idx * base_ty.size()) as isize,
                    ));
                    let zero_value = if value.is_global() {
                        value_table.program.new_value().zero_init(base_ty.clone())
                    } else {
                        value_table
                            .fd
                            .dfg()
                            .values()
                            .keys()
                            .next()
                            .copied()
                            .unwrap_or(value);
                        return Err(
                            "local aggregate zero-initialization should have been scalarized".into(),
                        );
                    };
                    emit_store_value(zero_value, sub_addr_reg, value_table, codes)?;
                }
                Ok(())
            }
            _ => Err(format!("unsupported aggregate store source: {:?}", value_data.kind())),
        },
        _ => Err(format!(
            "unsupported store value type in backend: {}",
            value_data.ty()
        )),
    }
}

fn emit_zero_store(
    ty: &Type,
    addr_reg: usize,
    value_table: &mut MyBBValueTable,
    codes: &mut Vec<String>,
) -> Result<(), String> {
    match ty.kind() {
        TypeKind::Int32 | TypeKind::Pointer(_) => {
            codes.push(format!(
                "  sw\t{}, 0({})",
                REGISTER_NAMES[0], REGISTER_NAMES[addr_reg]
            ));
            Ok(())
        }
        TypeKind::Array(base_ty, len) => {
            for idx in 0..*len {
                let (sub_addr_reg, addr_codes) = value_table.get_tmp_reg();
                codes.extend(addr_codes);
                codes.extend(add_reg_offset(
                    sub_addr_reg,
                    addr_reg,
                    (idx * base_ty.size()) as isize,
                ));
                emit_zero_store(base_ty, sub_addr_reg, value_table, codes)?;
            }
            Ok(())
        }
        _ => Err(format!("unsupported zero store type: {}", ty)),
    }
}

impl AssemblyBuildable for Program {
    fn build(&self, _: &Program) -> Result<Vec<String>, String> {
        let mut codes = vec![];

        if !self.inst_layout().is_empty() {
            codes.push("  .data".to_string());
            for inst in self.inst_layout() {
                codes.extend(self.borrow_value(*inst).build(self)?);
            }
        }

        let mut emitted_text = false;
        for func in self.func_layout() {
            let func_codes = self.func(*func).build(self)?;
            if func_codes.is_empty() {
                continue;
            }
            if !emitted_text {
                if !codes.is_empty() {
                    codes.push(String::new());
                }
                codes.push("  .text".to_string());
                emitted_text = true;
            } else {
                codes.push(String::new());
            }
            codes.extend(func_codes);
        }

        Ok(codes)
    }
}

fn binary_op_to_assembly(
    binary: &Binary,
    reg_ans: usize,

    reg_ans: usize,
    reg1: usize,
    reg2: usize,
) -> String {
    match binary.op() {
        koopa::ir::BinaryOp::Add => format!(
            "  add\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        koopa::ir::BinaryOp::Sub => format!(
            "  sub\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        koopa::ir::BinaryOp::Mul => format!(
            "  mul\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        koopa::ir::BinaryOp::Div => format!(
            "  div\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        koopa::ir::BinaryOp::Mod => format!(
            "  rem\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        koopa::ir::BinaryOp::And => format!(
            "  and\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        koopa::ir::BinaryOp::Or => format!(
            "  or\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        koopa::ir::BinaryOp::Xor => format!(
            "  xor\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        koopa::ir::BinaryOp::Shl => format!(
            "  sll\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        koopa::ir::BinaryOp::Shr => format!(
            "  srl\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        koopa::ir::BinaryOp::Sar => format!(
            "  sra\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        koopa::ir::BinaryOp::Eq => format!(
            "  xor\t{}, {}, {}\n  seqz\t{}, {}",
            REGISTER_NAMES[reg_ans],
            REGISTER_NAMES[reg1],
            REGISTER_NAMES[reg2],
            REGISTER_NAMES[reg_ans],
            REGISTER_NAMES[reg_ans]
        ),
        koopa::ir::BinaryOp::NotEq => format!(
            "  xor\t{}, {}, {}\n  snez\t{}, {}",
            REGISTER_NAMES[reg_ans],
            REGISTER_NAMES[reg1],
            REGISTER_NAMES[reg2],
            REGISTER_NAMES[reg_ans],
            REGISTER_NAMES[reg_ans]
        ),
        koopa::ir::BinaryOp::Lt => format!(
            "  slt\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        koopa::ir::BinaryOp::Gt => format!(
            "  sgt\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        koopa::ir::BinaryOp::Le => format!(
            "  sgt\t{}, {}, {}\n  seqz\t{}, {}",
            REGISTER_NAMES[reg_ans],
            REGISTER_NAMES[reg1],
            REGISTER_NAMES[reg2],
            REGISTER_NAMES[reg_ans],
            REGISTER_NAMES[reg_ans]
        ),
        koopa::ir::BinaryOp::Ge => format!(
            "  slt\t{}, {}, {}\n  seqz\t{}, {}",
            REGISTER_NAMES[reg_ans],
            REGISTER_NAMES[reg1],
            REGISTER_NAMES[reg2],
            REGISTER_NAMES[reg_ans],
            REGISTER_NAMES[reg_ans]
        ),
    }
}

fn emit_global_const(value: Value, program: &Program, codes: &mut Vec<String>) {
    let value_data = if value.is_global() {
        program.borrow_value(value).clone()
    } else {
        panic!("global aggregate contains non-global value");
    };
    match value_data.kind() {
        ValueKind::Integer(int) => codes.push(format!("  .word {}", int.value())),
        ValueKind::ZeroInit(_) => match value_data.ty().kind() {
            TypeKind::Int32 | TypeKind::Pointer(_) => codes.push("  .word 0".to_string()),
            TypeKind::Array(base_ty, len) => {
                for _ in 0..*len {
                    emit_global_zero(base_ty, codes);
                }
            }
            _ => {}
        },
        ValueKind::Aggregate(aggregate) => {
            for elem in aggregate.elems() {
                emit_global_const(*elem, program, codes);
            }
        }
        _ => panic!("invalid global constant value"),
    }
}

fn emit_global_zero(ty: &Type, codes: &mut Vec<String>) {
    match ty.kind() {
        TypeKind::Int32 | TypeKind::Pointer(_) => codes.push("  .word 0".to_string()),
        TypeKind::Array(base_ty, len) => {
            for _ in 0..*len {
                emit_global_zero(base_ty, codes);
            }
        }
        _ => {}
    }
}

fn init_global_aggregate(aggr: &Aggregate, program: &Program) -> Vec<String> {
    let mut codes = vec![];
    for elem in aggr.elems() {
        emit_global_const(*elem, program, &mut codes);
    }
    codes
}

impl AssemblyBuildable for ValueData {
    /// Used to handle global variable declarations.
    /// The ValueData's kind should be GlobalAlloc. Or it will panic.
    fn build(&self, program: &Program) -> Result<Vec<String>, String> {
        let alloc = match self.kind() {
            ValueKind::GlobalAlloc(alloc) => alloc,
            _ => panic!("invalid global declaration"),
        };
        let init = program.borrow_value(alloc.init());
        let mut codes = vec![format!(
            "{}:",
            assembly_symbol_name(self.name().as_ref().expect("global must be named"))
        )];
        match init.kind() {
            ValueKind::Integer(int) => codes.push(format!("  .word {}", int.value())),
            ValueKind::ZeroInit(_) => codes.push(format!("  .zero {}", init.ty().size())),
            ValueKind::Aggregate(aggregate) => codes.extend(init_global_aggregate(aggregate, program)),
            _ => {
                return Err(format!(
                    "unsupported global initializer in backend: {:?}",
                    init.kind()
                ))
            }
        }
        Ok(codes)
    }
}

impl AssemblyBuildable for FunctionData {
    fn build(&self, program: &Program) -> Result<Vec<String>, String> {
        if self.layout().bbs().is_empty() {
            return Ok(vec![]);
        }

        let func_name = assembly_symbol_name(self.name());
        let ret_label = format!(".{}_ret", func_name);

        let mut bb_labels = HashMap::new();
        for (idx, (bb, _)) in self.layout().bbs().iter().enumerate() {
            bb_labels.insert(*bb, bb_label(*bb, self, idx));
        }

        let mut value_table = MyBBValueTable::new(program, self);
        let mut max_call_extra_args = 0usize;
        for (_, node) in self.layout().bbs().iter() {
            for inst in node.insts().keys() {
                if let ValueKind::Call(call) = self.dfg().value(*inst).kind() {
                    max_call_extra_args = max_call_extra_args.max(
                        call.args()
                            .len()
                            .saturating_sub(REGISTER_FOR_ARGS.len())
                            * ARG_SIZE,
                    );
                }
            }
        }

        let mut next_offset = max_call_extra_args;
        for (_, node) in self.layout().bbs().iter() {
            for inst in node.insts().keys() {
                let inst_data = self.dfg().value(*inst);
                match inst_data.kind() {
                    ValueKind::Alloc(_) => {
                        let base_ty = match inst_data.ty().kind() {
                            TypeKind::Pointer(base_ty) => base_ty.clone(),
                            _ => {
                                return Err(format!(
                                    "alloc value does not have pointer type: {}",
                                    inst_data.ty()
                                ))
                            }
                        };
                        value_table.local_value_location.insert(*inst, next_offset);
                        next_offset += base_ty.size();
                    }
                    _ => {
                        if !inst_data.ty().is_unit() {
                            value_table.local_value_location.insert(*inst, next_offset);
                            next_offset += inst_data.ty().size();
                        }
                    }
                }
            }
        }
        value_table.stack_size = align_to(next_offset + ARG_SIZE, 16);
        let ra_offset = value_table.stack_size - ARG_SIZE;

        let mut codes = vec![
            format!("  .global {}", func_name),
            func_name.clone() + ":",
        ];
        codes.extend(stack_adjust_prologue(value_table.stack_size));
        codes.extend(value_table.store_with_offset(REG_RA, ra_offset as isize));

        for (bb, node) in self.layout().bbs().iter() {
            codes.push(bb_labels[bb].clone() + ":");
            for inst in node.insts().keys() {
                let inst_data = self.dfg().value(*inst);
                match inst_data.kind() {
                    ValueKind::Alloc(_) => {}
                    ValueKind::Load(load) => {
                        let mut inst_codes = vec![];
                        let (addr_reg, addr_codes) =
                            value_table.get_absolute_location(load.src());
                        inst_codes.extend(addr_codes);
                        let (dst_reg, dst_codes) =
                            value_table.want_to_visit_value(*inst, false, None);
                        inst_codes.extend(dst_codes);
                        inst_codes.push(format!(
                            "  lw\t{}, 0({})",
                            REGISTER_NAMES[dst_reg], REGISTER_NAMES[addr_reg]
                        ));
                        inst_codes.extend(clear_tracked_registers(&mut value_table));
                        codes.extend(inst_codes);
                    }
                    ValueKind::Store(store) => {
                        let mut inst_codes = vec![];
                        let (addr_reg, addr_codes) =
                            value_table.get_absolute_location(store.dest());
                        inst_codes.extend(addr_codes);
                        match lookup_value_data(store.value(), program, self).kind() {
                            ValueKind::ZeroInit(_)
                                if matches!(
                                    lookup_value_data(store.value(), program, self).ty().kind(),
                                    TypeKind::Array(_, _)
                                ) =>
                            {
                                emit_zero_store(
                                    lookup_value_data(store.value(), program, self).ty(),
                                    addr_reg,
                                    &mut value_table,
                                    &mut inst_codes,
                                )?;
                            }
                            _ => {
                                emit_store_value(
                                    store.value(),
                                    addr_reg,
                                    &mut value_table,
                                    &mut inst_codes,
                                )?;
                            }
                        }
                        inst_codes.extend(clear_tracked_registers(&mut value_table));
                        codes.extend(inst_codes);
                    }
                    ValueKind::Binary(binary) => {
                        let mut inst_codes = vec![];
                        let (lhs_reg, lhs_codes) =
                            value_table.want_to_visit_value(binary.lhs(), true, None);
                        inst_codes.extend(lhs_codes);
                        let (rhs_reg, rhs_codes) =
                            value_table.want_to_visit_value(binary.rhs(), true, None);
                        inst_codes.extend(rhs_codes);
                        let (dst_reg, dst_codes) =
                            value_table.want_to_visit_value(*inst, false, None);
                        inst_codes.extend(dst_codes);
                        inst_codes.push(binary_op_to_assembly(binary, dst_reg, lhs_reg, rhs_reg));
                        inst_codes.extend(clear_tracked_registers(&mut value_table));
                        codes.extend(inst_codes);
                    }
                    ValueKind::Jump(jump) => {
                        let mut inst_codes = clear_tracked_registers(&mut value_table);

                        let mut inst_codes = clear_tracked_registers(&mut value_table);
                        inst_codes.push(format!("  j\t{}", bb_labels[&jump.target()]));
                        codes.extend(inst_codes);
                    }
                    ValueKind::Branch(branch) => {
                        let mut inst_codes = vec![];
                        let (cond_reg, cond_codes) =
                            value_table.want_to_visit_value(branch.cond(), true, None);
                        inst_codes.extend(cond_codes);
                        inst_codes.extend(clear_tracked_registers(&mut value_table));
                        inst_codes.push(format!(
                            "  bnez\t{}, {}",
                            REGISTER_NAMES[cond_reg], bb_labels[&branch.true_bb()]
                        ));
                        inst_codes.push(format!("  j\t{}", bb_labels[&branch.false_bb()]));
                        codes.extend(inst_codes);
                    }
                    ValueKind::Call(call) => {
                        let mut inst_codes = clear_tracked_registers(&mut value_table);
                        for (idx, arg) in call.args().iter().copied().enumerate() {
                            if idx < REGISTER_FOR_ARGS.len() {
                                let (_, arg_codes) = value_table.want_to_visit_value(
                                    arg,
                                    true,
                                    Some(REGISTER_FOR_ARGS[idx]),
                                );
                                inst_codes.extend(arg_codes);
                            } else {
                                let (arg_reg, arg_codes) =
                                    value_table.want_to_visit_value(arg, true, None);
                                inst_codes.extend(arg_codes);
                                inst_codes.extend(value_table.store_with_offset(
                                    arg_reg,
                                    ((idx - REGISTER_FOR_ARGS.len()) * ARG_SIZE) as isize,
                                ));
                            }
                        }
                        inst_codes.push(format!(
                            "  call\t{}",
                            assembly_symbol_name(program.func(call.callee()).name())
                        ));
                        discard_caller_saved_registers(&mut value_table);
                        if !inst_data.ty().is_unit() {
                            let (_, ret_codes) =
                                value_table.want_to_visit_value(*inst, false, Some(REG_A0));
                            inst_codes.extend(ret_codes);
                        }
                        inst_codes.extend(clear_tracked_registers(&mut value_table));
                        codes.extend(inst_codes);
                    }
                    ValueKind::GetPtr(get_ptr) => {
                        let mut inst_codes = vec![];
                        let (base_reg, base_codes) =
                            value_table.get_absolute_location(get_ptr.src());
                        inst_codes.extend(base_codes);
                        let (idx_reg, idx_codes) =
                            value_table.want_to_visit_value(get_ptr.index(), true, None);
                        inst_codes.extend(idx_codes);
                        let (dst_reg, dst_codes) =
                            value_table.want_to_visit_value(*inst, false, None);
                        inst_codes.extend(dst_codes);

                        let step = match lookup_value_data(get_ptr.src(), program, self).ty().kind() {
                            TypeKind::Pointer(base_ty) => base_ty.size(),
                            _ => {
                                return Err(format!(
                                    "getptr source is not a pointer: {}",
                                    lookup_value_data(get_ptr.src(), program, self).ty()
                                ))
                            }
                        };

                        inst_codes.push(format!("  li\t{}, {}", REGISTER_NAMES[REG_X31], step));
                        inst_codes.push(format!(
                            "  mul\t{}, {}, {}",
                            REGISTER_NAMES[REG_X31], REGISTER_NAMES[idx_reg], REGISTER_NAMES[REG_X31]
                        ));
                        inst_codes.push(format!(
                            "  add\t{}, {}, {}",
                            REGISTER_NAMES[REG_X31], REGISTER_NAMES[base_reg], REGISTER_NAMES[REG_X31]
                        ));
                        if dst_reg != REG_X31 {
                            inst_codes.push(format!(
                                "  mv\t{}, {}",
                                REGISTER_NAMES[dst_reg], REGISTER_NAMES[REG_X31]
                            ));
                        }
                        inst_codes.extend(clear_tracked_registers(&mut value_table));
                        codes.extend(inst_codes);
                    }
                    ValueKind::GetElemPtr(get_elem_ptr) => {
                        let mut inst_codes = vec![];
                        let (base_reg, base_codes) =
                            value_table.get_absolute_location(get_elem_ptr.src());
                        inst_codes.extend(base_codes);
                        let (idx_reg, idx_codes) =
                            value_table.want_to_visit_value(get_elem_ptr.index(), true, None);
                        inst_codes.extend(idx_codes);
                        let (dst_reg, dst_codes) =
                            value_table.want_to_visit_value(*inst, false, None);
                        inst_codes.extend(dst_codes);

                        let step =
                            match lookup_value_data(get_elem_ptr.src(), program, self).ty().kind() {
                                TypeKind::Pointer(base_ty) => match base_ty.kind() {
                                    TypeKind::Array(elem_ty, _) => elem_ty.size(),
                                    _ => {
                                        return Err(format!(
                                            "getelemptr source is not a pointer to array: {}",
                                            lookup_value_data(get_elem_ptr.src(), program, self).ty()
                                        ))
                                    }
                                },
                                _ => {
                                    return Err(format!(
                                        "getelemptr source is not a pointer: {}",
                                        lookup_value_data(get_elem_ptr.src(), program, self).ty()
                                    ))
                                }
                            };

                        inst_codes.push(format!("  li\t{}, {}", REGISTER_NAMES[REG_X31], step));
                        inst_codes.push(format!(
                            "  mul\t{}, {}, {}",
                            REGISTER_NAMES[REG_X31], REGISTER_NAMES[idx_reg], REGISTER_NAMES[REG_X31]
                        ));
                        inst_codes.push(format!(
                            "  add\t{}, {}, {}",
                            REGISTER_NAMES[REG_X31], REGISTER_NAMES[base_reg], REGISTER_NAMES[REG_X31]
                        ));
                        if dst_reg != REG_X31 {
                            inst_codes.push(format!(
                                "  mv\t{}, {}",
                                REGISTER_NAMES[dst_reg], REGISTER_NAMES[REG_X31]
                            ));
                        }
                        inst_codes.extend(clear_tracked_registers(&mut value_table));
                        codes.extend(inst_codes);
                    }
                    ValueKind::Return(ret) => {
                        let mut inst_codes = vec![];
                        if let Some(value) = ret.value() {
                            let (_, value_codes) =
                                value_table.want_to_visit_value(value, true, Some(REG_A0));
                            inst_codes.extend(value_codes);
                        }
                        inst_codes.extend(clear_tracked_registers(&mut value_table));
                        inst_codes.push(format!("  j\t{}", ret_label));
                        codes.extend(inst_codes);
                    }
                    other => {
                        return Err(format!("unsupported instruction in backend: {:?}", other))
                    }
                }
            }
        }

        codes.push(ret_label + ":");
        codes.extend(value_table.load_with_offset(REG_RA, ra_offset as isize));
        codes.extend(stack_adjust_epilogue(value_table.stack_size));
        codes.push("  ret".to_string());
        Ok(codes)
    }
}

