fun @half(@x0: i32, @x1: i32, @x2: i32, @x3: i32, @x4: i32, @x5: i32, @x6: i32, @x7: i32, @x8: i32, @x9: i32, @x10: i32): i32 {
%bb0_entry:
  @x0_0 = alloc i32
  store @x0, @x0_0
  @x1_0 = alloc i32
  store @x1, @x1_0
  @x2_0 = alloc i32
  store @x2, @x2_0
  @x3_0 = alloc i32
  store @x3, @x3_0
  @x4_0 = alloc i32
  store @x4, @x4_0
  @x5_0 = alloc i32
  store @x5, @x5_0
  @x6_0 = alloc i32
